def process(load_phospho_proteomics) -> pd.DataFrame:
    df = load_phospho_proteomics.copy()
    df_idx = df[df['idx'].str.contains('CHEK2-S163', na=False)]

    if len(df_idx) == 0:
        return pd.DataFrame({'sample_id': [], 'CHEK2_S163': []})

    sample_cols = [col for col in df.columns if col.startswith('S') and col[1:].isdigit()]
    result_rows = []
    for _, row in df_idx.iterrows():
        for col in sample_cols:
            result_rows.append({'sample_id': col, 'CHEK2_S163': row[col]})

    return pd.DataFrame(result_rows)
